<?php
declare(strict_types=1);
require_once __DIR__.'/../../../src/config.php'; require_once __DIR__.'/../../../src/db.php'; header('Content-Type: application/json; charset=utf-8');
$key=$_SERVER['HTTP_X_API_KEY']??''; if(!hash_equals((string)env('N8N_API_KEY'),(string)$key)){http_response_code(401);echo json_encode(['error'=>'unauthorized']);exit;}
$d=json_decode(file_get_contents('php://input')?:'{}',true);
try{$sid=(string)($d['student_id']??'');$lvl=(string)($d['estimated_level']??'A1');$fb=trim((string)($d['written_feedback']??''));if($sid===''||$fb==='')throw new RuntimeException('student_id e written_feedback são obrigatórios.');db()->beginTransaction();$s=db()->prepare("INSERT INTO diagnostic_reports(student_id,estimated_level,confidence_score,strengths,weaknesses,detected_goals,written_feedback,study_plan,first_activity,delivered_at,delivery_channel,delivery_message_id) VALUES(:student_id,:estimated_level,:confidence_score,CAST(:strengths AS jsonb),CAST(:weaknesses AS jsonb),CAST(:detected_goals AS jsonb),:written_feedback,CAST(:study_plan AS jsonb),CAST(:first_activity AS jsonb),CASE WHEN :delivered THEN NOW() ELSE NULL END,:delivery_channel,:delivery_message_id) RETURNING id");$s->execute(['student_id'=>$sid,'estimated_level'=>$lvl,'confidence_score'=>$d['confidence_score']??null,'strengths'=>json_encode($d['strengths']??[],JSON_UNESCAPED_UNICODE),'weaknesses'=>json_encode($d['weaknesses']??[],JSON_UNESCAPED_UNICODE),'detected_goals'=>json_encode($d['detected_goals']??[],JSON_UNESCAPED_UNICODE),'written_feedback'=>$fb,'study_plan'=>json_encode($d['study_plan']??[],JSON_UNESCAPED_UNICODE),'first_activity'=>json_encode($d['first_activity']??[],JSON_UNESCAPED_UNICODE),'delivered'=>!empty($d['delivered']),'delivery_channel'=>$d['delivery_channel']??null,'delivery_message_id'=>$d['delivery_message_id']??null]);$rid=$s->fetchColumn();db()->prepare("UPDATE student_profiles SET estimated_level=:level,overall_level=:level,diagnostic_status='completed',diagnostic_completed_at=NOW(),updated_at=NOW() WHERE student_id=:student_id")->execute(['level'=>$lvl,'student_id'=>$sid]);db()->commit();echo json_encode(['ok'=>true,'report_id'=>$rid]);}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();http_response_code(500);echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}
